import{_ as d,C as t,o as n,c as i,E as a,a2 as o}from"./chunks/framework.Cc8dJFaW.js";const m=JSON.parse('{"title":"经验进入技能库前，先对准被测程序","description":"","frontmatter":{"title":"经验进入技能库前，先对准被测程序","article_type":"comparative-study","edition":"research-center","research_question":"可复用经验入库时，哪些精确程序、开发运行和建议构成接收依据？","summary":"程序成绩、建议判断与实际入库修改需要分别验收。两项研究与八组内部函数夹具说明精确程序绑定能检查什么，也留下逐条修改的语义对应问题。","sources":["https://arxiv.org/html/2611.33739v1","https://arxiv.org/html/2611.33560v1","https://raw.githubusercontent.com/lmsdss/Skeptic/bf0e78d2e2ce308d9d678e0bbb1196b5b3ad4ebb/skeptic/gate/promote.py"],"date":"2026-11-27","column":"open-source-engineering","category":"daily","pageClass":"runtime-v6-article","item_id":"SIG-20261127-002","lifecycle":"Published","cover":"/assets/covers/daily-2026-11-27-sig-20261127-002-2026-11-27-skill-evidence-cover.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"zh/engineering/2026-11-27-sig-20261127-002.md","filePath":"zh/engineering/2026-11-27-sig-20261127-002.md","lastUpdated":null}'),l={name:"zh/engineering/2026-11-27-sig-20261127-002.md"};function c(p,e,h,b,g,u){const r=t("ArticleCover"),s=t("ArticleTableScroll");return n(),i("div",null,[a(r,{image:"/assets/covers/daily-2026-11-27-sig-20261127-002-2026-11-27-skill-evidence-cover.png",kicker:"研究成果",title:"经验进入技能库前，先对准被测程序",summary:"程序成绩、建议判断与实际入库修改需要分别验收。两项研究与八组内部函数夹具说明精确程序绑定能检查什么，也留下逐条修改的语义对应问题。",version:"2026-11-27",languageHref:"/en/engineering/2026-11-27-sig-20261127-002",languageLabel:"English"}),a(s,{language:"zh"}),e[0]||(e[0]=o(`<h1 id="经验进入技能库前-先对准被测程序" tabindex="-1">经验进入技能库前，先对准被测程序 <a class="header-anchor" href="#经验进入技能库前-先对准被测程序" aria-label="Permalink to &quot;经验进入技能库前，先对准被测程序&quot;">​</a></h1><p>一份修复报告里有合理建议，来源程序也拿到了过线成绩，技能库就可以接收整份改动吗？现有研究把这个问题拆开了：程序能完成任务、建议值得保留、改动确实表达那条建议，是三个不同判断。维护共享技能库时，最值得追问的是“这份成绩究竟属于哪个程序，这段新文字又凭什么入库”。本文给出一组可核对的检查例子。</p><h2 id="两项研究-接收的对象并不相同" tabindex="-1">两项研究，接收的对象并不相同 <a class="header-anchor" href="#两项研究-接收的对象并不相同" aria-label="Permalink to &quot;两项研究，接收的对象并不相同&quot;">​</a></h2><p>技能库是供后续任务复用的策略与经验集合。把一次尝试写进去，影响就越过了当前任务。因此，比较接收机制之前，应先问它在批准什么。</p><p>RegHarness（机器人代码策略的运行约束与技能保留框架）区分运行内的动作提交和运行间的技能改进。按作者描述，一步代码需要无错误执行、验证者判断成功、审计者提出提交，才进入已提交代码；运行间改进则采用默认关闭的开关，检查关闭时的行为等价性与信息泄漏，再由作者选择启用。单次试验中技能库冻结。这是作者选择启用改进的流程，不能改写为“每条经验都自动通过相对旧版的证据验收”。<a href="https://arxiv.org/html/2611.33739v1" target="_blank" rel="noreferrer">原文第 3.1—3.6 节及附录（A—C）</a></p><p>Skeptic（以执行观测约束机器人失败诊断和技能发现的方法）提出另一种知识接收合同：在其 LIBERO（机器人操作任务基准）设置中，来源程序要在 15 个开发种子上至少成功 8 次，提议的修复还要获得新的验证者的合理性判断。这里的种子用于确定开发试验条件；分数不是对所有未来任务的保证。论文另为 Robosuite（机器人仿真环境）设置了 25 次中至少 14 次成功的门槛，不能把 8/15 当作通用阈值。<a href="https://arxiv.org/html/2611.33560v1" target="_blank" rel="noreferrer">原文第 3.3 节及附录（F—G）</a></p><table tabindex="0"><thead><tr><th>需要接收的对象</th><th>谁作决定、看什么</th><th>当前材料支持到哪里</th></tr></thead><tbody><tr><td>RegHarness 的一步代码</td><td>验证者与审计者检查执行结果、提出提交</td><td>来源陈述：单步提交条件；回放重跑代码，不是恢复完全相同的物理状态</td></tr><tr><td>RegHarness 的运行间改进</td><td>作者在开关、等价性和泄漏检查后选择启用</td><td>来源陈述：作者把关的改进；不是自动逐建议接收</td></tr><tr><td>Skeptic 的技能经验</td><td>独立于可编辑程序的接收服务，检查开发表现与验证结果</td><td>来源陈述及源码观察：来源程序取得接收资格；每条实际编辑的语义对应仍需另验</td></tr></tbody></table><p>两篇论文的作者与机构不同，可以作为这项合同比较的两个独立来源；它们没有相互复现效果。本文据此比较对象、证据和责任，不按两篇不同试验的成绩给系统排名。以上表格是研究综合，所列能力分别来自对应作者的陈述。</p><h2 id="成绩必须跟着同一份程序走" tabindex="-1">成绩必须跟着同一份程序走 <a class="header-anchor" href="#成绩必须跟着同一份程序走" aria-label="Permalink to &quot;成绩必须跟着同一份程序走&quot;">​</a></h2><p>Skeptic 公开的接收脚本在固定提交 <code>bf0e78d2e2ce308d9d678e0bbb1196b5b3ad4ebb</code>（固定提交标识）中，先对选定修复文件 <code>fix_code.py</code>（本轮选定的修复程序文件）计算内容哈希，再搜集尝试目录下已完成运行的程序副本。只有副本哈希相同的运行才参与统计。接着，它对每个开发种子保留运行名排序最大的结果，重算覆盖数和成功数；不是直接相信验证报告上的“8/15”。这里的“最新”来自脚本的运行名比较，不能扩展成因果顺序或跨主机时钟保证。<a href="https://raw.githubusercontent.com/lmsdss/Skeptic/bf0e78d2e2ce308d9d678e0bbb1196b5b3ad4ebb/skeptic/gate/promote.py" target="_blank" rel="noreferrer">接收脚本中的运行搜集与资格检查函数</a></p><p>下面是该固定源码中程序成绩部分的等价简化示意，用来说明对象关系，不是可直接调用的完整接口，也省略了报告检查：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>selected_hash = hash(selected_program)</span></span>
<span class="line"><span>matching_runs = finished_runs_with_program_hash(selected_hash)</span></span>
<span class="line"><span>latest_results = greatest_run_name_for_each_development_seed(matching_runs)</span></span>
<span class="line"><span>program_eligible = every_seed_is_covered(latest_results)</span></span>
<span class="line"><span>                   and count_successes(latest_results) &gt;= 8</span></span></code></pre></div><p>一个三秒钟的例子：程序改了一行，报告仍写着“8/15”。错误做法是沿用这张成绩；该脚本会重新寻找改后程序的运行。若旧记录里的副本都对应改前内容，新程序的覆盖数就是零。这说明哈希绑定在此处承担的是“成绩属于谁”，不是判断程序是否安全、建议是否正确。</p><h2 id="八组夹具-检查的是接收函数" tabindex="-1">八组夹具，检查的是接收函数 <a class="header-anchor" href="#八组夹具-检查的是接收函数" aria-label="Permalink to &quot;八组夹具，检查的是接收函数&quot;">​</a></h2><p>同日研究分析阶段已经执行了八组内部实验。它从上述固定源码提取三个未改写函数体：<code>sha_file</code>（文件内容哈希计算）、<code>program_runs</code>（程序运行搜集）和 <code>check</code>（接收资格检查），让它们读取合成的磁盘目录。实验环境为 Windows（操作系统）、Python（程序语言解释器）3.12.9；成功字段由夹具预置，没有启动机器人程序、模型、仿真器或传感器。本次写作只复用已完成的结果，不把八组检查说成新的机器人实验。<a href="/joinwell52/assets/evidence/2026-11-27-sig-20261127-002/skill-evidence.json">逐例结果与来源映射</a>、<a href="/joinwell52/assets/evidence/2026-11-27-sig-20261127-002/fixture-corpus.json">公开合成夹具集合</a></p><p>除表中变化外，基准设置均为：同一程序、15 个种子全覆盖、8 次成功、报告有一条被评为合理的建议。</p><table tabindex="0"><thead><tr><th>夹具变化</th><th>实际资格结果</th><th>本例回答的问题</th></tr></thead><tbody><tr><td>正向对照</td><td>符合</td><td>已披露条件在这个合成输入上可通过</td></tr><tr><td>成功数降至 7/15</td><td>不符合</td><td>门槛依据重算分数</td></tr><tr><td>仅有 14 个种子记录</td><td>不符合</td><td>已有 8 次成功也不能替代全覆盖</td></tr><tr><td>总体报告为驳回，仍有合理建议</td><td>符合</td><td>报告总体判断与单条建议判断不同</td></tr><tr><td>总体报告为无效，仍有合理建议</td><td>不符合</td><td>无效报告不能承担这次资格依据</td></tr><tr><td>没有合理建议</td><td>不符合</td><td>程序过线不能替代建议判断</td></tr><tr><td>修改选定程序、保留旧运行</td><td>不符合，覆盖数 0</td><td>程序身份改变后旧分数不能沿用</td></tr><tr><td>某个成功种子增加较新失败运行</td><td>不符合，重算为 7/15</td><td>同种子结果不能只挑旧成功</td></tr></tbody></table><p>八组实际结果均符合预先设置的预期。但“8/8 符合预期”是这组函数夹具的结果，不是任务成功率，也不是对接收服务全路径的覆盖。公开夹具集合以透明文本容器保留原包中这八个接收场景的 384 个成员文件，逐文件字节与校验信息保持不变。结果文件登记了源文件哈希、固定提交、提取函数、输入与输出，便于区分原始实验记录与本文解释。</p><h2 id="报告被驳回-为什么仍可能保留建议" tabindex="-1">报告被驳回，为什么仍可能保留建议 <a class="header-anchor" href="#报告被驳回-为什么仍可能保留建议" aria-label="Permalink to &quot;报告被驳回，为什么仍可能保留建议&quot;">​</a></h2><p>脚本接受的总体判断包括 <code>verified</code>（总体核实）和 <code>refuted</code>（总体驳回），排除 <code>void</code>（无效）；同时要求至少一条建议的处置是 <code>sound</code>（合理）。这不是本文为异常放行找的解释：源码开头明确说明，要求总体核实会让一个有缺陷条目拖累整份尝试；只有合理建议才应被保留。<a href="https://raw.githubusercontent.com/lmsdss/Skeptic/bf0e78d2e2ce308d9d678e0bbb1196b5b3ad4ebb/skeptic/gate/promote.py" target="_blank" rel="noreferrer">固定源码说明与检查条件</a></p><p>因此，“总体驳回但包含合理建议”是重要正向对照。若摘要把合同写成“只有总体核实的报告才能入库”，反而会抹掉它刻意保留的部分接受语义。</p><p>但还要问下一步：实际写入的每段文字，是否都对应那条合理建议？已检查的资格函数负责尝试级条件；源码中的后续处理会重查证据、拒绝旧技能库哈希并检查暂存内容格式，却没有在已读路径中显式逐条建立“编辑片段—合理建议”的语义映射。协调者的指令承担了只保留合理建议的要求。这是目前需要补验的保证边界，不是已复现的错误入库事故。协调者可能正确执行了指令；八组夹具既未执行后续写库处理，也未检验这种语义对应。</p><p>这给共享技能库维护者带来的研究判断是：<strong>程序级资格、建议级判断、编辑级对应关系应分别记账。</strong> 三者可以共同参与一次接收决定，但不能互相代替。“报告存在”也不能被当作三者都已成立。</p><h2 id="把下一项检查落在入库文字上" tabindex="-1">把下一项检查落在入库文字上 <a class="header-anchor" href="#把下一项检查落在入库文字上" aria-label="Permalink to &quot;把下一项检查落在入库文字上&quot;">​</a></h2><p>按这组证据，读者可以从一条候选经验出发，依次核对四件事：选定程序的内容哈希；开发种子的完整覆盖与每个种子的所选运行；每条建议的判断与对应来源；最终编辑片段和这些建议的对应关系。前三项在本文源码观察与函数夹具中各有不同程度的依据；第四项是建议补充的验收，不能标为当前已验证能力。</p><p>最有区分力的后续集成实验，是保留同一份过线程序和同一条合理建议，只改变待入库文字：一版忠实表达建议，另一版混入没有对应依据的结论，再观察真实接收服务如何处置。这个实验尚未执行，也不预判它会拒绝还是接收。</p><p>不适用边界也很具体。只结束会话的编排器没有在接收可复用知识，不能硬套技能晋升合同；8/15 是特定开发设置的政策，不能当作安全阈值；哈希一致只确认内容身份，不能弥补观测缺失。Skeptic 作者记录的反例中，某任务已有 12/15 开发成功，仍被错误地判断无法完成，且缺少旋钮角度测量。程序成绩并不自动修复任务关闭决定。RegHarness 作者也记录了错误提交、回放中止与治理引入的失败。本文没有复现这些整套试验，不能据此宣称普遍收益。<a href="https://arxiv.org/html/2611.33560v1" target="_blank" rel="noreferrer">诊断论文附录（C、E、H）</a>、<a href="https://arxiv.org/html/2611.33739v1" target="_blank" rel="noreferrer">运行约束论文第 4.4—4.7 节及附录</a></p><h2 id="证据与引用" tabindex="-1">证据与引用 <a class="header-anchor" href="#证据与引用" aria-label="Permalink to &quot;证据与引用&quot;">​</a></h2><p>本文把作者陈述、源码观察、内部实验和研究解释分开使用。作者陈述说明其方法与报告范围；源码观察只涉及固定文件；内部夹具实际检查有限函数；逐编辑验收则是从这些材料推导的后续建议。两个独立作者团队不等于彼此独立复现实验，论文公开也不自动增加结论强度。</p><ul><li>Shengming Liu（第一作者）等，机器人代码策略的运行约束与技能保留研究（英文原题：RegHarness: Regulating What Code-as-Policy Agents Keep from Steps to Skills），作者预印本，2026 年 11 月、v1。<a href="https://arxiv.org/html/2611.33739v1" target="_blank" rel="noreferrer">全文及附录</a>。支持单步提交与作者启用技能改进的合同；已准入材料没有实现代码与原始试验日志的复现。</li><li>Wenfang Sun（第一作者）等，以执行观测约束失败诊断和技能发现的研究（英文原题：Skeptic: Grounding Failure Diagnosis for Robot Skill Discovery），作者预印本，2026 年 11 月、v1。<a href="https://arxiv.org/html/2611.33560v1" target="_blank" rel="noreferrer">全文及附录</a>。支持程序开发表现、建议判断与失败反例的来源陈述。新的验证者是独立执行角色，不是独立研究机构。</li><li>Skeptic 项目的<a href="https://raw.githubusercontent.com/lmsdss/Skeptic/bf0e78d2e2ce308d9d678e0bbb1196b5b3ad4ebb/skeptic/gate/promote.py" target="_blank" rel="noreferrer">技能接收脚本</a>（固定提交：bf0e78d2e2ce308d9d678e0bbb1196b5b3ad4ebb）。与上一条合并为同一个作者来源；当前代码版本不被宣称为论文全部测量使用的确切版本。</li><li>研究中心，2026-11-27 内部函数实验：<a href="/joinwell52/assets/evidence/2026-11-27-sig-20261127-002/skill-evidence.json">八组结果、环境与映射</a>，<a href="/joinwell52/assets/evidence/2026-11-27-sig-20261127-002/fixture-corpus.json">合成输入集合</a>。支持程序证据检查的有限行为；不支持真实机器人收益、建议真值、逐编辑语义绑定或完整服务的安全结论。</li></ul>`,30))])}const f=d(l,[["render",c]]);export{m as __pageData,f as default};
